var ids=['signin','home','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];['Light','Dark'].forEach(function(a){var p=H.page('Proto iOS '+a);ids.forEach(function(id){var ss=p.layers.filter(function(l){return l.name==='Screen/ios/'+a+'/Clean/'+id;});if(ss.length!==1)throw Error('count '+a+id+ss.length);var s=ss[0],b=s.layers.find(function(l){return l.name==='body';});var borders=[],sizes={},dots=[],rings=[],links=[],children=[];function walk(l){if(l.style&&l.style.borders&&l.style.borders.some(function(b){return b.enabled;}))borders.push(l.name);if(l.type==='Text'&&!/^sf:/.test(l.name)){sizes[l.style.fontSize]=true;}if(l.name==='dot')dots.push(l.frame.width);if(l.name==='ring')rings.push(l.frame.width);if(/^link:/.test(l.name))links.push(l.name);(l.layers||[]).forEach(walk);}walk(s);b.layers.slice().reverse().forEach(function(l){children.push({name:l.name,y:l.frame.y,h:l.frame.height,bottom:l.frame.y+l.frame.height});});console.log(JSON.stringify({id:id,app:a+'/Clean',frame:String(s.id),parent:s.parent.name,w:s.frame.width,h:s.frame.height,borders:borders,sizes:Object.keys(sizes),dots:dots,rings:rings,links:links,body:{y:b.frame.y,h:b.frame.height,children:children}}));});});